function subtotal(items) { return items.reduce((sum, item) => sum + item, 0); }
function addFee(amount, fee) { return amount + fee; }
const base = subtotal([10, 20]);
console.log(addFee(base, 5));

function isPositive(n) { return n > 0; }
console.log(isPositive(3));
console.log(isPositive(-2));

function prepare() { return 'prepared'; }
function send() { return 'sent'; }
function workflow() { console.log(prepare()); console.log(send()); }
workflow();

function itemLine(name, qty) { return name + ' x ' + qty; }
console.log(itemLine('Pen', 2));
console.log(itemLine('Book', 1));
